from typing import Protocol
class Listener(Protocol):
    def changed(self, checked: bool) -> None: ...

from abc import ABC, abstractmethod
class Listener(ABC):
    @abstractmethod
    def changed(self, checked: bool) -> None: ...

from typing import overload
@overload
def run(flag: bool) -> str: ...
@overload
def run(flag: str) -> str: ...
def run(flag: bool | str) -> str: return str(flag)

class Service:
    @classmethod
    def run(cls, flag: bool): ...

class Service:
    @staticmethod
    def run(flag: bool): ...

from functools import singledispatch
@singledispatch
def convert(value): return str(value)
@convert.register
def _(value: bool): return str(value)
